import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
RAW_ORDERS = "/tmp/recon/raw_orders.json"
RAW_CUSTOMERS = "/tmp/recon/raw_customers.json"
MAX_PAGES = 1000

token = None
events = {"token_refresh": 0, "rate_limited": 0, "retried": 0}


def log(msg):
    print(msg, file=sys.stderr, flush=True)


class NotFound(Exception):
    pass


def get_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        token = json.load(r)["token"]
    events["token_refresh"] += 1


def retry_after_seconds(err, body):
    header = err.headers.get("Retry-After")
    if header is not None:
        return float(header)
    try:
        parsed = json.loads(body)
    except ValueError:
        parsed = None
    if isinstance(parsed, dict):
        for key in ("retry_after", "retry_after_seconds", "retryAfter"):
            if key in parsed:
                return float(parsed[key])
    raise RuntimeError(f"429 with no recognisable wait time: headers={dict(err.headers)} body={body[:300]}")


def call(path, auth=True):
    attempts = 0
    while True:
        attempts += 1
        if attempts > 30:
            raise RuntimeError(f"gave up on {path} after {attempts - 1} attempts")
        if auth and token is None:
            get_token()
        headers = {"Authorization": f"Bearer {token}"} if auth else {}
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            if e.code == 404:
                raise NotFound(path)
            if e.code == 401 and auth:
                log(f"{path}: 401, refreshing token")
                get_token()
                continue
            if e.code == 429:
                wait = retry_after_seconds(e, body)
                events["rate_limited"] += 1
                log(f"{path}: 429, waiting {wait}s")
                time.sleep(wait)
                continue
            events["retried"] += 1
            log(f"{path}: HTTP {e.code} attempt {attempts}: {body[:200]}")
            time.sleep(min(2 ** attempts, 20))
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            events["retried"] += 1
            log(f"{path}: transport error attempt {attempts}: {e}")
            time.sleep(min(2 ** attempts, 20))


def fetch_orders():
    pages = []
    path = "/orders?page=1"
    while path:
        if len(pages) >= MAX_PAGES:
            raise RuntimeError("page limit reached, pagination not terminating")
        data = call(path)
        if data.get("page") != len(pages) + 1:
            raise RuntimeError(f"unexpected page number {data.get('page')} at step {len(pages) + 1}")
        pages.append(data)
        path = data.get("next")
    total = pages[0]["total_pages"]
    if len(pages) != total:
        raise RuntimeError(f"fetched {len(pages)} pages but total_pages is {total}")
    return pages


def fetch_customers(ids):
    out = {}
    missing = []
    for cid in sorted(ids):
        try:
            out[cid] = call(f"/customers/{cid}")
        except NotFound:
            missing.append(cid)
    return out, missing


def main():
    pages = fetch_orders()
    items = [item for page in pages for item in page["items"]]
    with open(RAW_ORDERS, "w") as f:
        json.dump({"pages": [{"page": p["page"], "total_pages": p["total_pages"], "next": p["next"], "count": len(p["items"])} for p in pages], "items": items}, f)
    log(f"orders: {len(pages)} pages, {len(items)} listings")

    customer_ids = {item["customer_id"] for item in items}
    customers, missing = fetch_customers(customer_ids)
    with open(RAW_CUSTOMERS, "w") as f:
        json.dump({"customers": customers, "missing": missing}, f)
    log(f"customers: {len(customers)} fetched, {len(missing)} not found")
    log(f"events: {events}")


if __name__ == "__main__":
    main()

